  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Get a free hosted Postgres database in seconds: `npx create-db`\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// Location is a model where owners represent their business and add ressources, employees and other relevant needs\nmodel Location {\n  id             String          @id @default(cuid())\n  name           String\n  address        String\n  phone          String\n  users          UserLocation[]\n  inventoryItems InventoryItem[]\n  issueReports   IssueReport[]\n  ressources     Ressource[]\n  position       Position[]\n  inviteTokens   InviteToken[]\n}\n\n// User is a model that represents an individual working in a company.\nmodel User {\n  id                   String             @id @default(cuid())\n  firstname            String\n  lastname             String\n  email                String             @unique\n  passwordHash         String?\n  phone                String?\n  role                 Role\n  createdAt            DateTime           @default(now())\n  shiftAssignments     ShiftAssignment[]\n  locations            UserLocation[]\n  swapRequestsSent     ShiftSwapRequest[] @relation(\"SwapRequester\")\n  swapRequestsReceived ShiftSwapRequest[] @relation(\"SwapTarget\")\n  inventoryFlags       InventoryFlag[]\n  issueReports         IssueReport[]\n  ressources           Ressource[]\n  refreshTokens        RefreshToken[]\n  inviteTokens         InviteToken[]\n}\n\n// A model used for storing a newly created users invite token where it will be used for account setup.\nmodel InviteToken {\n  id        String   @id @default(cuid())\n  token     String   @unique\n  userId    String\n  user      User     @relation(fields: [userId], references: [id])\n  expiresAt DateTime\n  used      Boolean  @default(false)\n  lid       String\n  location  Location @relation(fields: [lid], references: [id])\n}\n\n// A model used for storing the users hashed refresh token. In case of a data breach, the raw value of refreshToken cannot be used to authenticate\nmodel RefreshToken {\n  id           String   @id @default(uuid())\n  refreshToken String   @unique\n  userId       String\n  user         User     @relation(fields: [userId], references: [id])\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt()\n  expiresAt    DateTime\n  revoked      Boolean  @default(false)\n}\n\n// A model used for assigning a user to a specific location with flags that indicates their status to that location\nmodel UserLocation {\n  userId     String\n  user       User     @relation(fields: [userId], references: [id])\n  locationId String\n  location   Location @relation(fields: [locationId], references: [id])\n  status     Status\n\n  @@id([userId, locationId])\n}\n\n// A model used for assigning a shift to a user with their position for that shift. Since a user can occupy many positions on different shifts, position\n// belongs on the shift not on the user.\nmodel ShiftAssignment {\n  id             String             @id @default(cuid())\n  userId         String\n  employee       User               @relation(fields: [userId], references: [id])\n  date           DateTime           @db.Date\n  start          String\n  end            String\n  positionId     String\n  position       Position           @relation(fields: [positionId], references: [id])\n  createdAt      DateTime           @default(now())\n  requesterShift ShiftSwapRequest[] @relation(\"RequesterShift\")\n  targetShift    ShiftSwapRequest[] @relation(\"TargetShift\")\n}\n\n// A model used for swapping 2 users shifts. Since 2 columns have the same references we require 2 named relations to distinguish them.\nmodel ShiftSwapRequest {\n  id               String          @id @default(cuid())\n  requesterId      String\n  targetId         String\n  requesterUser    User            @relation(\"SwapRequester\", fields: [requesterId], references: [id])\n  targetUser       User            @relation(\"SwapTarget\", fields: [targetId], references: [id])\n  requesterShiftId String\n  targetShiftId    String\n  requesterShift   ShiftAssignment @relation(\"RequesterShift\", fields: [requesterShiftId], references: [id])\n  targetShift      ShiftAssignment @relation(\"TargetShift\", fields: [targetShiftId], references: [id])\n  status           SwapStatus\n  createdAt        DateTime\n}\n\n// A model used to track a specific ressource. Information such as quantity, location, low in stock threshold and flags about the item initiated from a user are tracked\nmodel InventoryItem {\n  id             String          @id @default(cuid())\n  name           String\n  quantity       Int\n  unit           String\n  locationId     String\n  location       Location        @relation(fields: [locationId], references: [id])\n  lowThreshold   Int\n  updatedAt      DateTime        @updatedAt\n  inventoryFlags InventoryFlag[]\n}\n\n// A model used to create a flag about an item in the inventory.\nmodel InventoryFlag {\n  id              String        @id @default(cuid())\n  inventoryItemId String\n  inventoryItem   InventoryItem @relation(fields: [inventoryItemId], references: [id])\n  userId          String\n  flaggedBy       User          @relation(fields: [userId], references: [id])\n  note            String\n  flagStatus      FlagStatus\n  createdAt       DateTime\n}\n\n// A model used to issue reports such as a broken equipment or an incident or any problem. resolvedAt is optional, it's null when first reported because it hasn't been resolved yet\nmodel IssueReport {\n  id           String       @id @default(cuid())\n  userId       String\n  reportBy     User         @relation(fields: [userId], references: [id])\n  locationId   String\n  atLocation   Location     @relation(fields: [locationId], references: [id])\n  resolvedAt   DateTime?\n  note         String\n  reportStatus ReportStatus\n  createdAt    DateTime     @default(now())\n}\n\n// A model used for any ressource a business may have (e.g. recipe, procedures, contracts, etc)\nmodel Ressource {\n  id         String        @id @default(cuid())\n  userId     String\n  createdBy  User          @relation(fields: [userId], references: [id])\n  locationId String\n  location   Location      @relation(fields: [locationId], references: [id])\n  title      String\n  content    String\n  category   RessourceType\n  createdAt  DateTime      @default(now())\n}\n\n// A model where owners can define their own roles within their business. It belongs to a specific location and one position can belong to many different shifts\nmodel Position {\n  id               String            @id @default(cuid())\n  name             String\n  locationId       String\n  atLocation       Location          @relation(fields: [locationId], references: [id])\n  shiftAssignments ShiftAssignment[]\n  color            String            @default(\"gray\")\n}\n\nenum Status {\n  active\n  inactive\n  pending\n}\n\nenum SwapStatus {\n  pending_target\n  pending_manager\n  approved\n  rejected_by_target\n  rejected_by_manager\n}\n\nenum FlagStatus {\n  open\n  resolved\n}\n\nenum ReportStatus {\n  open\n  acknowledged\n  resolved\n}\n\nenum RessourceType {\n  recipe\n  procedure\n  policy\n}\n\nenum Role {\n  owner\n  manager\n  employee\n}\n"
